import { useCallback } from 'react';

import { FilterRegistry } from 'domain/Filter';
import {
  usePageFilterApplied,
  usePageFilterData,
  usePageFilterManagement,
} from 'hooks';
import { FilterValue } from 'models/Filters';

import { COMMERCIAL_RESULTS_PAGE_NAME } from '../../constants';

export const useCommercialResultsQuickFilterApply = () => {
  const { applyDirect } = usePageFilterManagement(COMMERCIAL_RESULTS_PAGE_NAME);
  const { applied } = usePageFilterApplied(COMMERCIAL_RESULTS_PAGE_NAME);
  const { appliedDataFilters } = usePageFilterData(
    COMMERCIAL_RESULTS_PAGE_NAME,
  );

  return useCallback(
    (key: string, value: FilterValue) => {
      if (key === 'zone') {
        const country = FilterRegistry.getDependentDefaultCascading(
          appliedDataFilters,
          'country',
          { ...applied, zone: value },
        );

        applyDirect({ zone: value, country });
        return;
      }

      if (key === 'brands') {
        applyDirect({
          brands: value,
          sub_brands: 'All',
          sku: 'All',
        });
        return;
      }

      applyDirect({ [key]: value });
    },
    [applied, appliedDataFilters, applyDirect],
  );
};
